def transform_v3(grid, separator_row):
    h, w = len(grid), len(grid[0])

    output = [[0]*w for _ in range(h)]
    for r in range(h):
        if r == separator_row:
            output[r] = [2]*w

    for col in range(w):
        col_cells = sorted([(grid[r][col], r) for r in range(h) if grid[r][col] != 0 and grid[r][col] != 2], 
                           key=lambda x: x[1])
        colors = [c[0] for c in col_cells]

        if not colors:
            continue

        n_col = len(colors)
        for idx, color in enumerate(colors):
            output[separator_row - 1 - idx][col] = color

    return output

