        cells = []
        q = [(start_r, start_c)]
        visited[start_r][start_c] = True
        while q:
            r,c = q.pop(0)
            cells.append((r,c))
            for dr,dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                nr,nc = r+dr, c+dc
                if 0<=nr<h and 0<=nc<w and not visited[nr][nc] and grid_c[nr][nc]==color:
